describe('Multi-Step Form Progress Indicator', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should display progress indicator as user navigates through form steps', () => {
    // Verify initial state: progress indicator should show step 1 of 3
    cy.get('[data-testid="progress-indicator"]').should('be.visible');
    cy.get('[data-testid="progress-step-1"]').should('contain', 'Step 1');
    cy.get('[data-testid="progress-step-2"]').should('contain', 'Step 2');
    cy.get('[data-testid="progress-step-3"]').should('contain', 'Step 3');

    // Fill in step 1
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('john@example.com');

    // Click next button to move to step 2
    cy.get('[data-testid="next-button"]').click();

    // Verify progress indicator updated to step 2
    cy.get('[data-testid="progress-step-1"]').should('have.class', 'completed');
    cy.get('[data-testid="progress-step-2"]').should('have.class', 'active');
    cy.get('[data-testid="progress-step-3"]').should('contain', 'Step 3');

    // Fill in step 2
    cy.get('[data-testid="address-input"]').type('123 Main St');
    cy.get('[data-testid="city-input"]').type('Anytown');

    // Click next button to move to step 3
    cy.get('[data-testid="next-button"]').click();

    // Verify progress indicator updated to step 3
    cy.get('[data-testid="progress-step-1"]').should('have.class', 'completed');
    cy.get('[data-testid="progress-step-2"]').should('have.class', 'completed');
    cy.get('[data-testid="progress-step-3"]').should('have.class', 'active');

    // Fill in step 3
    cy.get('[data-testid="phone-input"]').type('555-123-465');

    // Click submit button
    cy.get('[data-testid="submit-button"]').click();

    // Verify form submission success message
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');
  });

  it('should not allow navigation backward if form is incomplete', () => {
    // Fill in only step 1
    cy.get('[data-testid="name-input"]').type('Jane Doe');
    cy.get('[data-testid="email-input"]').type('jane@example.com');

    // Attempt to click next button without filling step 2
    cy.get('[data-testid="next-button"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please complete all required fields');

    // Verify progress indicator remains on step 1
    cy.get('[data-testid="progress-step-1"]').should('have.class', 'active');
    cy.get('[data-testid="progress-step-2"]').should('not.have.class', 'active');

    // Verify back button is disabled or not visible
    cy.get('[data-testid="back-button"]').should('be.disabled');

    // Fill in step 2 and try again
    cy.get('[data-testid="address-input"]').type('456 Oak Ave');
    cy.get('[data-testid="city-input"]').type('Springfield');

    // Click next button
    cy.get('[data-testid="next-button"]').click();

    // Verify progress indicator moves to step 2
    cy.get('[data-testid="progress-step-1"]').should('have.class', 'completed');
    cy.get('[data-testid="progress-step-2"]').should('have.class', 'active');
    cy.get('[data-testid="error-message"]').should('not.exist');
  });
});
